        Object metamodel=optional(factory,"getMetamodel"), selected=null;
        if(!providerObject(factory,metamodel))return bindingGap(report,"entity_unavailable");
        List<Object> types=values(optional(metamodel,"getEntities"),ENTITY_LIMIT+1);
        if(types.size()>ENTITY_LIMIT)return bindingGap(report,"entity_limit");
        for(Object candidate:types){
            if(providerObject(factory,candidate)&&classIs(candidate,JPA_DOMAIN+"EntityTypeImpl")&&
                bindingJavaClass(factory,optional(candidate,"getExpressibleJavaType")) instanceof Class<?> cls&&cls.getName().equals(entityName)){
                if(selected!=null)return bindingGap(report,"entity_ambiguous");
                selected=candidate;
            }
        }
        if(selected==null)return bindingGap(report,"entity_unavailable");
        String[] path=propertyPath.split("\\.");
        Class<?> declared=null;
        String kind=null;
        for(int i=0;i<path.length;i++){
            Object attribute=optional(selected,"getAttribute",path[i]);
            if(!providerObject(factory,attribute))return bindingGap(report,"attribute_unavailable");
            Object attributeKind=optional(attribute,"getPersistentAttributeType");
            Class<?> type=bindingJavaClass(factory,optional(attribute,"getAttributeJavaType"));
            if(!(attributeKind instanceof Enum<?> enumeration)||type==null){
                return bindingGap(report,"attribute_unavailable");
            }
            kind=enumeration.name();
            declared=type;
            if(i+1<path.length){
                if(!kind.equals("EMBEDDED"))return bindingGap(report,"unsupported_jpa_path");
                selected=optional(attribute,"getType");
                if(!providerObject(factory,selected)||!classIs(selected,JPA_DOMAIN+"EmbeddableTypeImpl")){
                    return bindingGap(report,"unsupported_jpa_path");
                }
            }
        }
        report.put("declaration",map("basis","jakarta-persistence-metamodel","kind",kind,"javaType",declared.getTypeName()));
        report.put("state","partial");
        if(!"BASIC".equals(kind))return bindingGap(report,"unsupported_jpa_kind");

        Object runtimeModel=optional(factory,"getMappingMetamodel");
        if(!providerObject(factory,runtimeModel))return bindingGap(report,"mapping_unavailable");
        Object mapping=optional(runtimeModel,"findEntityDescriptor",entityName);
        if(!providerFamily(factory,mapping,"org.hibernate.persister.entity.")||!PERSISTERS.contains(mapping.getClass().getSimpleName())){
            return bindingGap(report,"mapping_unavailable");
        }
        for(int i=0;i<path.length;i++){
            Object attribute=optional(mapping,"findAttributeMapping",path[i]);
            if(attribute==null&&i==0)attribute=optional(mapping,"findSubPart",path[i]);
            if(!providerFamily(factory,attribute,MAPPING))return bindingGap(report,"mapping_unavailable");
            mapping=attribute;
            if(i+1<path.length){
                if(!classIs(mapping,MAPPING+"EmbeddedAttributeMapping"))return bindingGap(report,"unsupported_provider_path");
                mapping=optional(mapping,"getEmbeddableTypeDescriptor");
                if(!providerFamily(factory,mapping,MAPPING))return bindingGap(report,"unsupported_provider_path");
            }
        }
        if(!classIs(mapping,MAPPING+"BasicAttributeMapping")&&!classIs(mapping,MAPPING+"BasicEntityIdentifierMappingImpl")){
            return bindingGap(report,"unsupported_provider_mapping");
        }
        if(!Boolean.FALSE.equals(optional(mapping,"isFormula")))return bindingGap(report,"unsupported_selectable");
        String table=bindingName(optional(mapping,"getContainingTableExpression"));
        String column=bindingName(optional(mapping,"getSelectionExpression"));
        if(table==null||column==null)return bindingGap(report,"selectable_unavailable");
        Object jdbc=optional(mapping,"getJdbcMapping");
        if(!providerFamily(factory,jdbc,HIBERNATE_TYPE+"internal.")||!BINDING_TYPES.contains(jdbc.getClass().getSimpleName())){
            return bindingGap(report,"unsupported_provider_type");
        }

        try{
            // Trusted Hibernate wrappers return registered descriptors or cached binders.
            // Never ask a bean for a converter instance or call a conversion/binding method.
            Object converter=invoke(jdbc,"getValueConverter");
            if(converter!=null&&(!providerObject(factory,converter)||
                !classIs(converter,HIBERNATE_TYPE+"descriptor.converter.internal.AttributeConverterBean"))){
                return bindingGap(report,"unsupported_converter");
            }
            Class<?> domain=bindingJavaClass(factory,optional(jdbc,"getMappedJavaType"));
            Class<?> relational=bindingJavaClass(factory,optional(jdbc,"getJdbcJavaType"));
            Map<String,Object> conversion=Map.of("kind","no-registered-converter");
            if(converter!=null){
                Class<?> converterClass=bindingJavaClass(factory,optional(converter,"getConverterJavaType"));
                if(converterClass==null||bindingJavaClass(factory,optional(converter,"getDomainJavaType"))!=domain||
                    bindingJavaClass(factory,optional(converter,"getRelationalJavaType"))!=relational){
                    return bindingGap(report,"converter_metadata_unavailable");
                }
                conversion=Map.of("kind","attribute-converter","javaType",converterClass.getName());
            }
            if(domain==null||relational==null||boxed(declared)!=boxed(domain))return bindingGap(report,"java_type_unavailable");
            Object jdbcType=optional(jdbc,"getJdbcType");
            if(!providerFamily(factory,jdbcType,HIBERNATE_TYPE+"descriptor.jdbc.")||
                !(optional(jdbcType,"getJdbcTypeCode") instanceof Integer number)){
                return bindingGap(report,"jdbc_metadata_unavailable");
            }
            Class<?> owner=jdbc.getClass().getMethod("getJdbcValueBinder").getDeclaringClass();
            if(!owner.getName().equals(HIBERNATE_TYPE+"AbstractStandardBasicType")&&
                !owner.getName().equals(HIBERNATE_TYPE+"internal.ConvertedBasicTypeImpl")){
                return bindingGap(report,"jdbc_binder_unavailable");
            }
            Object binder=optional(jdbc,"getJdbcValueBinder");
            if(!providerFamily(factory,binder,HIBERNATE_TYPE+"descriptor.jdbc."))return bindingGap(report,"jdbc_binder_unavailable");
            String type=JDBCType.valueOf(number).name();
            report.put("mapping",map("basis","hibernate-runtime-mapping","table",table,"column",column,
                "domainJavaType",domain.getTypeName(),"relationalJavaType",relational.getTypeName(),"conversion",conversion,
                "jdbcTypeCode",number,"jdbcType",type,"binderClass",binder.getClass().getName()));
            report.put("state","observed");
            return report;
        }catch(Throwable unsupported){
            return bindingGap(report,"jdbc_metadata_unavailable");
        }
    }

    private static Map<String,Object> bindingGap(Map<String,Object> report,String reason){report.put("reason",reason);return report;}
    private static String bindingName(Object value){
        return value instanceof String field&&!field.isBlank()&&field.length()<=256&&field.chars().noneMatch(Character::isISOControl)?field:null;
    }
    private static boolean classIs(Object value,String name){return value!=null&&value.getClass().getName().equals(name);}
    private static boolean providerFamily(Object factory,Object value,String prefix){
        return value!=null&&value.getClass().getName().startsWith(prefix)&&providerObject(factory,value);
    }
    private static boolean providerObject(Object factory,Object value){
        if(value==null)return false;
        Class<?> origin=factory.getClass(), actual=value.getClass();
        if(actual.getClassLoader()!=origin.getClassLoader())return false;
        var expected=origin.getProtectionDomain().getCodeSource();
        var received=actual.getProtectionDomain().getCodeSource();
        return expected!=null&&received!=null&&expected.getLocation()!=null&&received.getLocation()!=null&&
            expected.getLocation().toExternalForm().equals(received.getLocation().toExternalForm());
    }
    private static Class<?> bindingJavaClass(Object factory,Object descriptor){
        if(!providerFamily(factory,descriptor,HIBERNATE_TYPE+"descriptor.java."))return null;
        try{
            Method getter=descriptor.getClass().getMethod("getJavaType");
            String owner=getter.getDeclaringClass().getName();
            String base=HIBERNATE_TYPE+"descriptor.java.";
            if(!owner.equals(base+"AbstractClassJavaType")&&!owner.equals(base+"AbstractJavaType")&&
                !owner.equals(base+"spi.UnknownBasicJavaType"))return null;
            return getter.invoke(descriptor) instanceof Class<?> type?type:null;
        }catch(ReflectiveOperationException unavailable){return null;}
    }

    private static final String GRAPH="org.hibernate.graph.internal.";
    private static final int GRAPH_COUNT_LIMIT=24, GRAPH_PATH_LIMIT=64, GRAPH_DEPTH_LIMIT=6;

    static Map<String,Object> namedEntityGraphs(Object factory){
        Map<String,Object> result=map("state","unknown","observerExecutedSql",false,"valuesRetained",false,
            "applicationCallbacksInvoked",false,"graphs",List.of());
        if(!classIs(factory,"org.hibernate.internal.SessionFactoryImpl")||!Boolean.FALSE.equals(optional(factory,"isClosed"))){
            result.put("reason","factory_unavailable");
            return result;
        }
        Object metamodel=optional(factory,"getMetamodel");
        if(!providerObject(factory,metamodel)){
            result.put("reason","graph_registry_unavailable");
            return result;
        }
        Object entities=optional(metamodel,"getEntities");
        if(!(entities instanceof Set<?> managed)){
            result.put("reason","graph_registry_unavailable");
            return result;
        }
        if(managed.size()>128){
            result.put("reason","graph_registry_limit");
            return result;
        }
        // The verified Hibernate implementation requires a concrete managed Java type here.
        Map<String,Object> available=new LinkedHashMap<>();
        Set<String> changed=new java.util.HashSet<>();
        boolean complete=true;
        for(Object entity:managed){
            if(!classIs(entity,JPA_DOMAIN+"EntityTypeImpl")||!providerObject(factory,entity)){complete=false;continue;}
            Class<?> type=bindingJavaClass(factory,optional(entity,"getExpressibleJavaType"));
            Object registered=type==null?null:optional(factory,"getNamedEntityGraphs",type);
            if(!(registered instanceof Map<?,?> names)){complete=false;continue;}
            if(names.size()>GRAPH_COUNT_LIMIT){result.put("reason","graph_registry_limit");return result;}
            for(var entry:names.entrySet()){
                String name=graphName(entry.getKey());
                Object graph=entry.getValue();
                if(name==null||graph==null){complete=false;continue;}
                Object prior=available.putIfAbsent(name,graph);
                if(prior!=null&&prior!=graph){complete=false;changed.add(name);}
            }
            if(available.size()>GRAPH_COUNT_LIMIT){result.put("reason","graph_registry_limit");return result;}
        }
        List<Map<String,Object>> graphs=new ArrayList<>();
        for(var entry:available.entrySet()){
            String name=entry.getKey();
            if(changed.contains(name))continue;
            Map<String,Object> graph=readEntityGraph(factory,entry.getValue());
            if(graph==null||!name.equals(graph.get("name"))){complete=false;continue;}
            complete&=Boolean.TRUE.equals(graph.get("complete"));
            graphs.add(graph);
        }
        graphs.sort(Comparator.comparing(value->(String)value.get("name")));
        result.put("basis","jakarta-named-entity-graphs");
        result.put("state",complete?"observed":"partial");
        result.put("graphs",List.copyOf(graphs));
        return result;
    }

    static Map<String,Object> appliedEntityGraph(Object factory,Object context){
        try{
            if(!classIs(factory,"org.hibernate.internal.SessionFactoryImpl")||
                !providerFamily(factory,context,"org.hibernate."))return null;
            Object queryOptions=optional(context,"getQueryOptions");
            if(!providerFamily(factory,queryOptions,"org.hibernate."))return null;
            Object applied=optional(queryOptions,"getAppliedGraph");
            if(!providerFamily(factory,applied,"org.hibernate."))return null;
            Object graph=optional(applied,"getGraph"), mode=optional(applied,"getSemantic");
            if(!(mode instanceof Enum<?> semantic)||!Set.of("FETCH","LOAD").contains(semantic.name()))return null;
            Map<String,Object> described=readEntityGraph(factory,graph);
            if(described==null)return null;
            return map("semantic",semantic.name(),"graph",described);
        }catch(Throwable ignored){return null;}
    }

    private static Map<String,Object> readEntityGraph(Object factory,Object graph){
        if(!classIs(graph,GRAPH+"RootGraphImpl")||!providerObject(factory,graph))return null;
        Object model=optional(graph,"getGraphedType");
        if(!classIs(model,JPA_DOMAIN+"EntityTypeImpl")||!providerObject(factory,model))return null;
        Class<?> type=bindingJavaClass(factory,optional(model,"getExpressibleJavaType"));
        if(type==null||type.getName().length()>256)return null;
        Object rawName=optional(graph,"getName");
        String name=graphName(rawName);
        List<String> paths=new ArrayList<>();
        boolean complete=(rawName==null||name!=null)&readGraphPaths(factory,graph,"",0,paths,new IdentityHashMap<>());
        paths.sort(String::compareTo);
        return map("name",name,"rootJavaType",type.getName(),"paths",List.copyOf(paths),"complete",complete);
    }

    private static boolean readGraphPaths(Object factory,Object graph,String prefix,int depth,List<String> paths,
                                           IdentityHashMap<Object,Boolean> ancestors){
        if(depth>=GRAPH_DEPTH_LIMIT||ancestors.put(graph,Boolean.TRUE)!=null)return false;
        try{
            Object attributes=invoke(graph,"getAttributeNodeList");
            if(!(attributes instanceof List<?> nodes))return false;
            boolean complete=invoke(graph,"getTreatedSubgraphs") instanceof Map<?,?> treated&&treated.isEmpty();
            for(Object node:nodes){
                if(paths.size()>=GRAPH_PATH_LIMIT)return false;
                if(!providerFamily(factory,node,GRAPH+"AttributeNodeImpl$")){complete=false;continue;}
                Object attribute=invoke(node,"getAttributeName");
                if(!(attribute instanceof String name)||!name.matches("[A-Za-z_$][A-Za-z0-9_$]{0,127}")){
                    complete=false;
                    continue;
                }
                String path=prefix.isEmpty()?name:prefix+"."+name;
                if(path.length()>256||paths.contains(path)){complete=false;continue;}
                paths.add(path);
                // Ordinary value-subgraphs retain their path; map-key and treated branches require separate semantics.
                if(invoke(node,"getKeySubgraph")!=null)complete=false;
                Object child=invoke(node,"getValueSubgraph");
                if(child!=null){
                    if(!classIs(child,GRAPH+"SubGraphImpl")||!providerObject(factory,child))complete=false;
                    else complete&=readGraphPaths(factory,child,path,depth+1,paths,ancestors);
                }
            }
            return complete;
        }catch(Throwable unavailable){return false;}
        finally{ancestors.remove(graph);}
    }

    private static String graphName(Object value){
        return value instanceof String name&&name.matches("[A-Za-z0-9_.$: -]{1,128}")&&!name.isBlank()?name:null;
    }

    static List<Class<?>> observedManagedClasses(Object factory,int limit){
        if(!classIs(factory,"org.hibernate.internal.SessionFactoryImpl")||!Boolean.FALSE.equals(optional(factory,"isClosed")))return null;
        Object metamodel=optional(factory,"getMetamodel");
        if(!providerObject(factory,metamodel)||!(optional(metamodel,"getManagedTypes") instanceof Set<?> types)||types.size()>limit)return null;
        List<Class<?>> classes=new ArrayList<>();
        Set<String> names=new java.util.HashSet<>();
        for(Object model:types){
            if(!providerFamily(factory,model,JPA_DOMAIN))return null;
            Class<?> type=bindingJavaClass(factory,optional(model,"getExpressibleJavaType"));
            if(type==null||type.getName().length()>256||
                !type.getName().matches("[A-Za-z_$][A-Za-z0-9_$.]{0,255}")||!names.add(type.getName()))return null;
            classes.add(type);
        }
        classes.sort(Comparator.comparing(Class::getName));
        return List.copyOf(classes);
    }

    private static Map<String, Object> function(Object registry, String name) {
        Map<String, Object> result = map("name", text(name, 256), "state", "observed");
        Object descriptor = optional(registry, "findFunctionDescriptor", name);
        if (descriptor == null) { descriptor = optional(registry, "findSetReturningFunctionDescriptor", name); result.put("setReturning", true); }
        if (descriptor == null) { result.put("state", "unknown"); return result; }
        result.put("descriptorClass", descriptor.getClass().getName());
        Object kind = optional(descriptor, "getFunctionKind"); if (kind instanceof Enum<?> e) result.put("kind", e.name());
        result.put("signature", string(optional(descriptor, "getSignature", name)));
        Object validator = optional(descriptor, "getArgumentsValidator");
        String signature = string(optional(validator, "getSignature")); result.put("argumentSignature", signature);
        String returns = string(optional(descriptor, "getReturnSignature"));
        if (returns == null) returns = string(optional(optional(descriptor, "getReturnTypeResolver"), "getReturnType"));
        result.put("returnSignature", returns);
        result.put("returns", map("state", "unknown", "reason", "Display signatures do not establish a context-independent Java return type. Use a concrete semantic probe for query-specific types."));
        List<Map<String, Object>> args = new ArrayList<>(); result.put("arguments", args);
        // Parse only a finite signature emitted by Hibernate's exact public validator.
        if (signature != null && validator != null && validator.getClass().getName().equals("org.hibernate.query.sqm.produce.function.ArgumentTypesValidator") && signature.matches("\\((?:[A-Z_]+ arg[0-9]*(?:, [A-Z_]+ arg[0-9]*)*)?\\)")) {
            Matcher matcher = Pattern.compile("([A-Z_]+) arg[0-9]*").matcher(signature);
            while (matcher.find() && args.size() < 64) args.add(map("category", matcher.group(1), "state", "observed"));
            result.put("minArgs", args.size()); result.put("maxArgs", args.size());
        } else result.put("argumentTypesState", "unknown");
        return result;
    }

    static String javaType(Object node) {
        if (node == null) return null; if (node instanceof Class<?> c) return c.getName();
        for (String name : new String[]{"getJavaTypeClass", "getJavaType", "getBindableJavaType", "getParameterType"}) { Object value = optional(node, name); if (value instanceof Class<?> c) return c.getName(); }
        for (String name : new String[]{"getNodeJavaType", "getExpressibleJavaType", "getJavaTypeDescriptor"}) { Object descriptor = optional(node, name); if (descriptor != null && descriptor != node) { Object value = optional(descriptor, "getJavaTypeClass"); if (value instanceof Class<?> c) return c.getName(); } }
        Object type = optional(node, "getNodeType"); if (type != null && type != node) { Object descriptor = optional(type, "getExpressibleJavaType"); Object value = optional(descriptor, "getJavaTypeClass"); if (value instanceof Class<?> c) return c.getName(); }
        return null;
    }

    private static Map<String, Object> base(Object factory) {
        String version = null;
        if (factory != null) {
            try { Class<?> type = Class.forName("org.hibernate.Version", false, factory.getClass().getClassLoader()); Object value = type.getMethod("getVersionString").invoke(null); if (value instanceof String s) version = text(s, 128); } catch (Throwable ignored) {}
            if (version == null) version = factory.getClass().getPackage().getImplementationVersion();
        }
        return map("provider", "hibernate", "version", version);
    }
    private static Map<String, Object> unknown(Map<String, Object> result, String code, String message, Throwable error) {
        result.put("state", "unknown");
        @SuppressWarnings("unchecked") List<Map<String, Object>> diagnostics = (List<Map<String, Object>>) result.computeIfAbsent("diagnostics", ignored -> new ArrayList<>());
        diagnostics.add(diagnostic(code, message, error)); return result;
    }
    private static Map<String, Object> diagnostic(String code, String message, Throwable error) {
        Map<String, Object> value = map("code", code, "message", message);
        if (error != null) value.put("exceptionType", unwrap(error).getClass().getName());
        // Provider messages may echo query literals. Never return/log the raw message.
        return value;
    }
    private static boolean semanticFailure(Throwable error) {
        int depth = 0;
        for (Throwable cause = error; cause != null && depth++ < 16; cause = cause.getCause()) {
            String name = cause.getClass().getName();
            if (name.startsWith("org.hibernate.query.") && (name.endsWith("Exception") || name.endsWith("Error"))) return true;
            if (name.equals("org.hibernate.QueryException") || name.startsWith("org.hibernate.grammars.hql.")) return true;
        }
        return false;
    }
    private static Throwable unwrap(Throwable value) { int depth = 0; while (value instanceof InvocationTargetException e && e.getCause() != null && depth++ < 16) value = e.getCause(); return value; }
    static Object optional(Object receiver, String name, Object... args) { try { return receiver == null ? null : invoke(receiver, name, args); } catch (Throwable ignored) { return null; } }
    static Object invoke(Object receiver, String name, Object... args) throws Throwable {
        if (receiver == null) throw new NoSuchMethodException(name);
        Method chosen = null;
        for (Method method : receiver.getClass().getMethods()) {
            if (!method.getName().equals(name) || method.getParameterCount() != args.length || Modifier.isStatic(method.getModifiers())) continue;
            boolean match = true; Class<?>[] types = method.getParameterTypes();
            for (int i = 0; i < args.length; i++) if (args[i] == null ? types[i].isPrimitive() : !boxed(types[i]).isInstance(args[i])) { match = false; break; }
            if (match) { chosen = accessible(receiver.getClass(), method); if (chosen != null) break; }
        }
        if (chosen == null) throw new NoSuchMethodException(receiver.getClass().getName() + "." + name);
        try { return chosen.invoke(receiver, args); } catch (InvocationTargetException error) { throw unwrap(error); }
    }
    private static Method accessible(Class<?> receiver, Method method) {
        if (Modifier.isPublic(method.getDeclaringClass().getModifiers())) return method;
        return declaration(receiver, method.getName(), method.getParameterTypes(), new java.util.HashSet<>());
    }
    private static Method declaration(Class<?> type, String name, Class<?>[] parameters, Set<Class<?>> seen) {
        if (type == null || !seen.add(type)) return null;
        if (Modifier.isPublic(type.getModifiers())) { try { Method method = type.getMethod(name, parameters); if (Modifier.isPublic(method.getDeclaringClass().getModifiers())) return method; } catch (NoSuchMethodException ignored) {} }
        for (Class<?> contract : type.getInterfaces()) { Method method = declaration(contract, name, parameters, seen); if (method != null) return method; }
        return declaration(type.getSuperclass(), name, parameters, seen);
    }
    private static Class<?> boxed(Class<?> type) { if (!type.isPrimitive()) return type; return switch (type.getName()) { case "int" -> Integer.class; case "boolean" -> Boolean.class; case "long" -> Long.class; case "double" -> Double.class; case "float" -> Float.class; case "short" -> Short.class; case "byte" -> Byte.class; case "char" -> Character.class; default -> Void.class; }; }
    private static List<Object> values(Object value, int limit) {
        List<Object> result = new ArrayList<>(); if (limit <= 0 || value == null) return result;
        if (value instanceof Iterable<?> iterable) { for (Object item : iterable) { if (result.size() >= limit) break; result.add(item); } }
        else if (value.getClass().isArray()) { for (int i = 0; i < Math.min(Array.getLength(value), limit); i++) result.add(Array.get(value, i)); }
        return result;
    }
    private static List<String> stringValues(Object value, int limit) { List<String> result = new ArrayList<>(); for (Object item : values(value, limit)) if (item instanceof String s) result.add(text(s, 512)); return result; }
    private static String string(Object value) { return value instanceof String s ? text(s, 512) : null; }
    private static Number number(Object value) { return value instanceof Number n ? n : null; }
    private static boolean hierarchyContains(Object value, String className) { if (value == null) return false; for (Class<?> type = value.getClass(); type != null; type = type.getSuperclass()) if (type.getName().equals(className)) return true; return false; }
    private static String text(Object value, int limit) { if (!(value instanceof String s)) return ""; return s.substring(0, Math.min(s.length(), limit)).replaceAll("[\\x00-\\x08\\x0b\\x0c\\x0e-\\x1f]", ""); }
    private static Map<String, Object> map(Object... pairs) { Map<String, Object> value = new LinkedHashMap<>(); for (int i = 0; i < pairs.length; i += 2) value.put((String) pairs[i], pairs[i + 1]); return value; }
    private static long estimatedBytes(Object value, int depth) {
        if (depth > 32) return PAYLOAD_LIMIT;
        if (value == null) return 4; if (value instanceof String s) return 2L + s.getBytes(StandardCharsets.UTF_8).length * 6L;
        if (value instanceof Number || value instanceof Boolean) return 32;
        long count = 2;
        if (value instanceof Map<?, ?> map) for (Map.Entry<?, ?> entry : map.entrySet()) count += estimatedBytes(entry.getKey(), depth + 1) + estimatedBytes(entry.getValue(), depth + 1) + 2;
        else if (value instanceof Collection<?> list) for (Object item : list) count += estimatedBytes(item, depth + 1) + 1;
        return count;
    }
