                "(Ljakarta/persistence/EntityManager;"+DEFINITION+")"+ARG_OBJECT);
            boolean finish=(hook==Hook.COMMIT||hook==Hook.ROLLBACK)&&call(element,ENTITY_TX,hook.key,"()V");
            if(begin||finish){
