                if(linked!=null&&linked.resultAccepted&&!linked.redispatchStarted){
                    linked.redispatchStarted=true;
                    request.set(new Request(linked,Phase.REDISPATCH,servletRequest));
                    return;
                }
                if(linked!=null)linked.incomplete=true;
