            trace.entered.add(type);
        }catch(Throwable ignored){trace.incomplete=true;}
    }
    public static void decision(boolean granted){
        Trace trace=outer();if(trace==null)return;
        if(trace.decision!=null){trace.incomplete=true;return;}
